// AI: below section was generated by an AI
const labels = {
	idle: "Ready",
	preparing: "Preparing image",
	queued: "Waiting for device",
	downloading: "Transferring",
	verifying: "Verifying image",
	rebooting: "Waiting for reboot",
	complete: "Build verified after reboot",
	error: "Update failed",
};

// A build ID establishes equality; a version label alone cannot order two rebuilds of the same release.
export function firmwareState(device) {
	const phase = device.updateState || "idle";
	const size = Number(device.updateSize) || 0,
		offset = Math.min(size, Number(device.updateOffset) || 0);
	const progress =
		size > 0 && ["queued", "downloading", "verifying", "rebooting"].includes(phase)
			? " · " + Math.floor((100 * offset) / size) + "% (" + offset + "/" + size + " bytes)"
			: "";
	const legacy =
		device.updateTelemetry === false && ["queued", "downloading", "verifying", "rebooting"].includes(phase);
	return {
		phase,
		label: (device.online === false ? "Offline · " : "") + (labels[phase] || phase) + progress,
		detail: legacy
			? (device.result || "") +
				" · Older firmware does not report byte progress; completion requires a verified build after reboot."
			: device.result || device.commandResult || "",
	};
}

export function renderFirmware(status, get) {
	get("autoUpdateStatus").textContent =
		status.autoUpdateStatus || "Automatic update status unavailable on this firmware";
	const local = status.devices.find((device) => device.id === status.localId);
	const followers = status.devices.filter((device) => device.id !== status.localId);
	const peers = followers.filter((device) => device.online !== false);
	const previous = get("firmwareTarget").value;
	get("firmwareTarget").replaceChildren(
		new Option(peers.length ? "All followers with a different or unknown build" : "No connected followers", "all"),
	);
	for (const peer of peers) {
		const same = status.stagedBuild && peer.buildId === status.stagedBuild;
		get("firmwareTarget").append(
			new Option(
				(peer.name || peer.id) + (peer.simulated ? " (simulator)" : "") + (same ? " — already has staged build" : ""),
				peer.id,
			),
		);
	}
	if ([...get("firmwareTarget").options].some((option) => option.value === previous))
		get("firmwareTarget").value = previous;
	get("firmwareSource").textContent =
		"This device: " +
		(local?.version || "unknown version") +
		" · build " +
		(local?.buildId?.slice(0, 12) || "unknown (older firmware)") +
		(status.staged
			? "\nReady image: " +
				(status.imageSource === "running" ? "this device’s running firmware" : "uploaded file") +
				" · build " +
				(status.stagedBuild?.slice(0, 12) || "unknown")
			: "\nNo image is ready to send.");
	get("firmwareDevices").replaceChildren();
	for (const device of status.devices) {
		const state = firmwareState(device),
			row = document.createElement("tr");
		row.classList.toggle("updateError", state.phase === "error");
		row.classList.toggle("updateComplete", state.phase === "complete");
		for (const value of [
			(device.name || device.id) + (device.id === status.localId ? " (this device)" : ""),
			(device.version || "Unknown") + "\n" + (device.buildId?.slice(0, 12) || "Build unknown"),
			state.label,
			state.detail,
		]) {
			const cell = document.createElement("td");
			cell.textContent = value;
			row.append(cell);
		}
		get("firmwareDevices").append(row);
	}
	const master = (status.firmwareManager ?? status.master) && status.settled;
	const active = status.preparingCurrent || status.uploadActive;
	const allCurrent = !!local?.buildId && peers.length > 0 && peers.every((peer) => peer.buildId === local.buildId);
	get("firmwareHint").textContent =
		master && status.canShareCurrent !== true
			? "This source firmware cannot share its running image yet. Install the current firmware build over USB first; file upload remains available."
			: !master
				? "Send firmware from the elected master at " + status.masterIp + "."
				: !peers.length
					? "No follower is connected. A connected follower will appear here before you can send firmware."
					: allCurrent
						? "All connected followers already report this device’s build."
						: "Choose a follower or send to all different/unknown builds. Progress and errors stay visible in this table.";
	const transferring = followers.some((peer) =>
		["queued", "downloading", "verifying", "rebooting"].includes(peer.updateState),
	);
	get("shareCurrent").disabled =
		!master || !peers.length || active || transferring || status.canShareCurrent !== true || allCurrent;
	get("shareCurrent").title =
		status.canShareCurrent === true ? "" : "This device needs a firmware update before it can share its running image";
	get("rollout").disabled = !master || !peers.length || !status.staged || active || transferring;
	get("installLocal").disabled =
		!master ||
		!status.staged ||
		active ||
		transferring ||
		(status.stagedBuild && status.stagedBuild === local?.buildId);
	get("firmwareTarget").disabled = !master || active || transferring;
	get("upload").disabled = !master || active || transferring;
	get("firmwareStatus").textContent = status.firmwareStatus || "Ready";
	if (status.preparingCurrent) {
		get("progress").hidden = false;
		get("progress").value = status.prepareSize ? Math.floor((100 * status.prepareOffset) / status.prepareSize) : 0;
		get("firmwareStatus").textContent += " · " + status.prepareOffset + "/" + status.prepareSize + " bytes";
	} else if (!status.uploadActive) get("progress").hidden = true;
}

// Preparation is incremental on the ESP32. Never queue a rollout until the selected source is actually ready.
export async function shareCurrentFirmware(rpc, refresh, target) {
	await rpc({ op: "prepareCurrent" });
	const deadline = Date.now() + 180000;
	while (Date.now() < deadline) {
		await new Promise((resolve) => setTimeout(resolve, 300));
		const status = await refresh();
		if (!(status.firmwareManager ?? status.master))
			throw new Error("Firmware management is no longer available from this source.");
		if (status.preparingCurrent) continue;
		if (!status.staged || status.imageSource !== "running")
			throw new Error(status.firmwareStatus || "Preparing the running firmware failed");
		return rpc({ op: "rollout", target });
	}
	throw new Error("Preparing the running firmware timed out");
}
